#include "eternity/game/purchases.hpp"
#include "eternity/game/character_core_save.hpp"
#include "eternity/game/inventory_save.hpp"
#include "eternity/game/creation.hpp"
#include <iostream>

using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint64_t value,unsigned int count) {for(unsigned int i=0;i<count;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
struct BoughtItem {std::uint8_t slot;std::uint64_t uid;std::uint32_t id=5001;std::uint16_t quality=100;};
net::Packet purchase(std::string code,std::uint32_t price,std::initializer_list<BoughtItem> items,std::uint8_t make='U') {
    net::Packet p{2,14};put(p,9701,4);code.resize(21,0);p.insert(p.end(),code.begin(),code.end());put(p,price,4);put(p,pack_world_time(std::chrono::sys_days{std::chrono::year{2024}/2/29}+std::chrono::hours{23}+std::chrono::minutes{59}+std::chrono::seconds{58}),4);p.push_back(make);p.push_back(static_cast<std::uint8_t>(items.size()));for(const auto& row:items) {put(p,row.uid,8);put(p,row.id,4);p.insert(p.end(),{1,row.slot,5,1,10});put(p,row.quality,2);p.insert(p.end(),{1,2,3,4,5,6});const std::string craft="01020304050607080903X";p.insert(p.end(),craft.begin(),craft.end());}return p;
}
}
int main(int argc,char** argv) {
    try {
        require(argc==2 && std::string_view(argv[1]).starts_with("Eternity_Test_Creation_"),"Purchase SQL test requires disposable catalog");const std::string catalog=argv[1],prefix="["+catalog+"].dbo.";const auto config=storage::SqlServerConfig::from_environment();storage::SqlServer db(config),points_db(config);const auto definitions=Definitions::load(db);const auto rules=CreationRules::load(definitions);const auto time=std::chrono::sys_days{std::chrono::year{2024}/1/1};Characters characters(db,1,time,catalog);require(characters.save_country(9701,0,true),"Cannot initialize purchase fixture account");auto draft=rules.prepare({0,0,2,0,0,0,0,0,"PurchaseHero"},0);draft.items.clear();const auto created=characters.create(9701,"buy_user",draft,time);require(created.result==0,"Cannot create purchase fixture character");const auto cid=std::to_string(created.character_id);
        db.query("INSERT "+prefix+"Users_Master(UserUID,UserID,Pw,Admin,AdminLevel,UseQueue,Status,[Leave],UserType,Enpassword,Point) VALUES(9701,'buy_user','testpass',0,0,0,0,0,'N','',1000),(9702,'purchase_other','testpass',0,0,0,0,0,'N','',500);");
        PlayerCore initial;initial.user_id=9701;initial.character=draft.character;initial.character.id=created.character_id;initial.money=99;InventoryReplicaPool pool;CharacterReplica cache(initial,pool);cache.purchases().load_history({},1000);PurchaseStore store(db,points_db,catalog);CharacterCoreStore core(db,catalog);InventoryStore inventory(db,1,catalog);std::size_t diagnostics=0;const auto diagnostic=[&](std::string_view text){require(!text.empty(),"Empty purchase diagnostic");++diagnostics;};
        const auto stage=[&](const net::Packet& p){require(cache.apply(p)==InventoryReplicaResult::applied,"Cannot stage purchase");};
        const auto balance=[&](){return db.query("SELECT Point FROM "+prefix+"Users_Master WHERE UserUID=9701;")[0].rows[0][0];};
        stage(purchase("buy_success",100,{{0,UINT64_MAX-20},{1,UINT64_MAX-21,5001,65535}}));require(cache.purchases().pending_count()==1 && cache.inventory().inventory().size()==2,"Purchase did not stage two inventory and frozen SQL copies");
        net::Packet count{0x17,6};put(count,9701,4);count.insert(count.end(),{1,0,7});require(cache.apply(count)==InventoryReplicaResult::applied,"Cannot mutate purchase inventory before SQL");
        bool rejected=false;db.begin();try{store.save(cache.purchases(),created.character_id,diagnostic);}catch(const std::logic_error&){rejected=true;}db.rollback();require(rejected && cache.purchases().pending_count()==1 && balance()==storage::Cell{"1000"},"Purchase joined caller transaction or changed state on rejection");rejected=false;try{PurchaseStore invalid(db,db,catalog);}catch(const std::invalid_argument&){rejected=true;}require(rejected,"Purchase accepted one shared DB connection");
        auto saved=store.save(cache.purchases(),created.character_id,diagnostic);require(saved.legacy_success && saved.saved==1 && !saved.retained && !saved.discarded && !cache.purchases().pending_count() && cache.purchases().history()[0].save_type==0 && !diagnostics && balance()==storage::Cell{"900"},"Original purchase commit or point deduction failed");
        auto rows=db.query("SELECT ItemUID,[Count],Quality,Gem1,Gem6,Craftname,CONVERT(varchar(19),MakeTime,120),MakeType FROM "+prefix+"CharItems WHERE CharID="+cid+" ORDER BY Slot; SELECT UsePoint,ProductCode,CONVERT(varchar(19),UseDate,120) FROM "+prefix+"PointLog WHERE CharID="+cid+";");
        require(rows[0].rows==std::vector<storage::Row>{{storage::Cell{"-21"},storage::Cell{"10"},storage::Cell{"100"},storage::Cell{"1"},storage::Cell{"6"},storage::Cell{"01020304050607080903"},storage::Cell{"2024-02-29 23:59:58"},storage::Cell{"U"}},{storage::Cell{"-22"},storage::Cell{"10"},storage::Cell{"0"},storage::Cell{"1"},storage::Cell{"6"},storage::Cell{"01020304050607080903"},storage::Cell{"2024-02-29 23:59:58"},storage::Cell{"U"}}},"Frozen purchase SQL metadata/normalization/truncation changed");require(rows[1].rows==std::vector<storage::Row>{{storage::Cell{"100"},storage::Cell{"buy_success"},storage::Cell{"2024-02-29 23:59:58"}}},"Original point purchase log changed");require(cache.inventory().inventory()[0].item.count==7 && cache.inventory().inventory()[0].save_type==2 && cache.purchases().packet()[6]==0xe8 && cache.purchases().packet()[7]==3,"Purchase SQL overwrote later inventory mutation or refreshed original cash cache");
        // The earlier item purchase and separate point charge survive a later
        // character transaction rollback. Its dirty inventory write can retry.
        db.begin();core.save_in_transaction(cache);inventory.save_in_transaction(cache.inventory(),created.character_id);db.rollback();rows=db.query("SELECT Money FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT [Count] FROM "+prefix+"CharItems WHERE CharID="+cid+" AND Slot=0;");require(rows[0].rows[0][0]==storage::Cell{"0"} && rows[1].rows[0][0]==storage::Cell{"10"} && balance()==storage::Cell{"900"},"Character rollback reached previously committed purchase/charge");db.begin();core.save_in_transaction(cache);inventory.save_in_transaction(cache.inventory(),created.character_id);db.commit();cache.core_save_success();cache.inventory().inventory_save_success();require(store.save(cache.purchases(),created.character_id,diagnostic).saved==0 && balance()==storage::Cell{"900"},"Empty purchase save charged again");
        // Insufficient points roll back the account procedure's attempted reset
        // to zero, discard frozen copies, and leave its history slot reserved.
        stage(purchase("insufficient",1000,{{2,0x7777000000000a02ULL}}));saved=store.save(cache.purchases(),created.character_id,diagnostic);require(!saved.legacy_success && saved.discarded==1 && saved.saved==0 && !cache.purchases().pending_count() && cache.purchases().history()[0].save_type==1 && balance()==storage::Cell{"900"},"Insufficient-point failure did not retain original discard/history/rollback behavior");rows=db.query("SELECT COUNT(*) FROM "+prefix+"CharItems WHERE CharID="+cid+" AND Slot=2;");require(rows[0].rows[0][0]==storage::Cell{"0"},"Rejected charge left a free inventory SQL row");
        stage(purchase("item_failure",20,{{3,0x7777000000000a03ULL},{4,0x7777000000000a04ULL,2147483000}}));saved=store.save(cache.purchases(),created.character_id,diagnostic);require(!saved.legacy_success && saved.discarded==1 && balance()==storage::Cell{"900"} && cache.purchases().history()[1].save_type==1,"Item insert error charged points or reset failed history");rows=db.query("SELECT COUNT(*) FROM "+prefix+"CharItems WHERE CharID="+cid+" AND Slot IN (3,4);");require(rows[0].rows[0][0]==storage::Cell{"0"},"Purchase insert error left earlier rows committed");
        stage(purchase("mixed_first",20,{{5,0x7777000000000a05ULL}}));stage(purchase("mixed_fail",9999,{{6,0x7777000000000a06ULL}}));stage(purchase("mixed_last",30,{{7,0x7777000000000a07ULL}}));saved=store.save(cache.purchases(),created.character_id,diagnostic);require(!saved.legacy_success && saved.saved==2 && saved.discarded==1 && !saved.retained && !cache.purchases().pending_count() && balance()==storage::Cell{"850"},"Purchase save did not continue after a discarded queue entry");rows=db.query("SELECT Slot FROM "+prefix+"CharItems WHERE CharID="+cid+" AND Slot IN (5,6,7) ORDER BY Slot;");require(rows[0].rows==std::vector<storage::Row>{{storage::Cell{"5"}},{storage::Cell{"7"}}},"Mixed purchase queue committed the wrong items");
        stage(purchase("negative_cost",static_cast<std::uint32_t>(-50),{{8,0x7777000000000a08ULL}}));saved=store.save(cache.purchases(),created.character_id,diagnostic);require(saved.legacy_success && saved.saved==1 && balance()==storage::Cell{"900"},"Original signed DWORD point cost changed");rows=db.query("SELECT UsePoint FROM "+prefix+"PointLog WHERE CharID="+cid+" AND ProductCode='negative_cost';");require(rows[0].rows[0][0]==storage::Cell{"-50"},"Signed point cost did not reach original account procedure/log");
        stage(purchase("empty_purchase",0,{}));saved=store.save(cache.purchases(),created.character_id,diagnostic);require(saved.legacy_success && saved.saved==1 && balance()==storage::Cell{"900"},"Original zero-item purchase was not saved");
        stage(purchase("bad_make",1,{{9,0x7777000000000a09ULL}},0));saved=store.save(cache.purchases(),created.character_id,diagnostic);require(!saved.legacy_success && saved.discarded==1 && balance()==storage::Cell{"900"},"Bound empty MakeType repaired original purchase SQL error");
        PlayerSnapshot loaded;loaded.core=initial;loaded.cash_points=900;loaded.catalogs["PointLog"]=db.query("EXEC "+prefix+"usp_Read_Chars_PointLog_R "+cid+";")[0];CharacterReplica reloaded(initial,pool);require(reloaded.purchases().load(loaded) && reloaded.purchases().packet()[10]==loaded.catalogs["PointLog"].rows.size(),"Original SQL purchase history/calendar did not reload");for(const auto& row:reloaded.purchases().history()) require(row.save_type==0,"Reload retained failed purchase reservation");rows=db.query("SELECT Point FROM "+prefix+"Users_Master WHERE UserUID=9702; SELECT COUNT(*) FROM "+prefix+"PointLog WHERE UserUID=9702;");require(rows[0].rows[0][0]==storage::Cell{"500"} && rows[1].rows[0][0]==storage::Cell{"0"} && !db.transaction_active() && !points_db.transaction_active(),"Purchase reached another account or leaked transactions");
        std::cout<<"Original purchase SQL passed: two connections, frozen copies, account charge/log, independent commits, insufficient points, item rollback, mixed queue, signed costs and history reload\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
